#!/usr/bin/env python3
"""Writes scratch/reviews/pads-core/lna-bond-model.spice: the coupled bond model of lnabench.py as subcircuits (options A/B x min/nom/max)."""
import os, sys, types
src = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), 'lnabench.py')).read().split('HDR = [')[0]
m = types.ModuleType('lb'); m.__file__ = os.path.abspath(__file__); exec(src, m.__dict__)
out = ['* LNA / RF_RX bond model on the standard 74-wire layout (pads owner, 2026-11-18). Generated by scratch/pads-core/lnagnd/export_model.py',
       '* from bondl.py (0.8 mil wire, two-segment loop, image ground plane; analytic filament model, NOT EM, not measured).',
       '* Ports: BRD_P BRD_N = board ends of the RF_RX_P / RF_RX_N wires (finger; add trace, via, connector and the match yourself)',
       '*        PAD_P PAD_N = die pads; VSS = die VSS at the pad ring; VDD = die supply ring; board ground = node 0.',
       '* Inside: the RX pair, ground bonds 63 71 73 and supply bonds 64 72 74 individually with every mutual (K), each wire 0.25 ohm;',
       '*        supply fingers go to board ground through 1.2 nH (trace + via + 1 uF 0201); the other 7 ground bonds are one 0.314 nH,',
       '*        the other 5 supply bonds one 0.46 nH + 0.24 nH. No on-die ring impedance, no decap (add your own between VDD and VSS).',
       '* Option A = RF_RX on bonds 70 / 69 (today). Option B = RF_RX on bonds 68 / 67 (proposed, swap with BB_I). Cases min / nom / max = loop and plane bounds.']
for opt in 'AB':
    for case in ('min', 'nom', 'max'):
        net, L, bonds = m.bond_net(case, opt)
        ren = lambda l: ' '.join({'bp': 'BRD_P', 'bn': 'BRD_N', 'padp': 'PAD_P', 'padn': 'PAD_N', 'vss': 'VSS', 'vdd': 'VDD'}.get(t, t) for t in l.split())
        out += [f'.subckt rfrx_bond_{opt}_{case} BRD_P BRD_N PAD_P PAD_N VSS VDD'] + [ren(l) for l in net] + [f'.ends rfrx_bond_{opt}_{case}']
open('/work/../scratch/reviews/pads-core/lna-bond-model.spice' if False else sys.argv[1], 'w').write('\n'.join(out) + '\n'); print(len(out), 'lines')
